export const safetyModule2Path = "/study/safety/module-2";
export const safetyModule2Sources = {
  whmis:{title:"WSIB WHMIS OSHA New",slides:42},
  confined:{title:"Confined Space Practices – New",slides:57},
  ramp:{title:"Hangar and Ramp Safety Pt 3 – Flight Line Safety New",slides:50},
  towing:{title:"Aircraft Towing and Movement – New",slides:49},
  loto:{title:"Lock Out Tag Out Procedures – New",slides:27},
};
export const safetyModule2Choice = [], safetyModule2Recall = [], safetyModule2NoteSections = [];
function topic(id,title,deck,rows) {
  const items=[];
  for(const [target,label,definition,slides,prompt,recallPrompt,word,aliases=[]] of rows) {
    const explanation=`${definition} (${safetyModule2Sources[deck].title}, slides ${slides.join(", ")}.)`;
    const peers=rows.filter(row=>row[0]!==target).map(row=>row[1]);
    const source={deck,slides};
    safetyModule2Choice.push({id:`safety2-${target}`,topic:id,learningTarget:target,prompt,options:[label,...peers.slice(0,3)],correctIndex:0,explanation,source});
    if(recallPrompt) safetyModule2Recall.push({id:`safety2-word-${target}`,topic:id,learningTarget:target,prompt:recallPrompt,answer:word,acceptedAnswers:[word,...aliases],explanation,source});
    items.push([label,explanation]);
  }
  safetyModule2NoteSections.push({id:`safety2-${id}`,title,items});
}

topic("rights","Worker rights, responsibilities & reporting","whmis",[
  ["right-know","Right to know","Workers have a right to know about workplace health and safety hazards. Information lets them recognize risks; participation and refusal are separate rights.",[7],"A worker asks to be told about the hazards in their work area. Which fundamental right is involved?","The right to _____ concerns being informed about workplace hazards.","know"],
  ["right-participate","Right to participate","Workers have a right to participate in health and safety decisions. The deck describes employees and management working together through a joint committee.",[7],"A worker wants a voice in workplace health and safety decisions. Which right applies?","Workers have the right to _____ in health and safety decisions.","participate"],
  ["right-refuse","Right to refuse","The course identifies a right to refuse work that endangers health or safety. This is distinct from simply receiving hazard information; the applicable workplace process governs its use.",[7],"Which right addresses a worker being asked to do work that endangers health or safety?","The right to _____ concerns work that endangers health or safety.","refuse"],
  ["joint-committee","Joint Health and Safety Committee","The deck describes employees and management forming the joint committee. The joint arrangement supports worker participation rather than leaving safety decisions to one side alone.",[7],"Which group brings employees and management together on workplace health and safety?","Employees and management form the _____ Health and Safety Committee.","joint"],
  ["wsib-premiums","Employer insurance premiums","The WSIB example describes employers paying premiums for no-fault collective-liability insurance. The premiums fund the insurance arrangement rather than being a worker training requirement.",[5],"In the course's WSIB example, what do employers pay into the insurance arrangement?","In the WSIB example, employers pay insurance _____.","premiums",["premium"]],
  ["wsib-benefits","Loss-of-earnings benefits and health-care coverage","The deck describes injured workers receiving earnings benefits and health-care coverage under WSIB. These benefits address consequences of injury, rather than serving as hazard labels or work permits.",[5],"What assistance does the WSIB slide describe for injured workers?","The WSIB slide pairs health-care coverage with loss-of-_____ benefits.","earnings"],
  ["report-correction","Corrective action rather than discipline","The course describes safety reporting that encourages disclosure of genuine mistakes with an emphasis on corrective action. Intentional falsification and criminal activity are excluded in its example, so this is not a promise of immunity for every act.",[9,10],"What emphasis does the course's safety-reporting example place on genuine mistakes?","The reporting example emphasizes _____ action rather than discipline for genuine mistakes.","corrective"],
  ["report-falsification","Intentional falsification is excluded","The example's acceptance conditions exclude intentional falsification. Reporting a genuine error differs from deliberately creating false information; the course does not treat them as equivalent.",[10],"Which condition would exclude a report under the course's reporting-program example?","The reporting example excludes intentional _____ of information.","falsification"],
]);

topic("whmis","Hazard communication, labels & responsibilities","whmis",[
  ["whmis-elements","Labels, safety data sheets and worker education","The three principal WHMIS elements communicate hazards and teach workers how to use the information. A label alone is not the whole program: SDS information and education are also needed.",[13],"Which combination forms the three principal WHMIS elements in the lesson?","Alongside labels and SDSs, WHMIS includes worker _____.","education",["training"]],
  ["supplier-role","Supplier classification, labelling and SDS provision","The supplier determines whether products are hazardous, labels them and provides SDSs. Employer availability/training and employee participation are separate responsibilities.",[16],"A manufacturer supplies a hazardous product. Which responsibility set belongs to the supplier?","Suppliers must provide Safety Data _____ for hazardous products.","sheets",["sheet"]],
  ["employer-role","Employer labelling, SDS availability and training","Employers ensure containers are labelled, SDSs are available and workers are trained. Receiving a labelled container does not remove the employer's duty to make information usable at work.",[17],"Which responsibility set belongs to the employer using hazardous products?","Employers must ensure workers receive WHMIS _____.","training",["education"]],
  ["employee-role","Employee training participation and information use","Employees participate in training and understand labels, SDSs, handling, storage, disposal and emergencies. Having information on a shelf is insufficient if workers cannot use it.",[18],"Which responsibility set belongs to employees handling hazardous products?","Employees must _____ in WHMIS training and use the information.","participate"],
  ["workplace-label","Workplace label for a transferred product","The lesson describes a workplace label when chemicals are transferred into another container. It identifies the product and safe handling, with an SDS reference, so the smaller container does not become unidentified.",[17,22,23],"A chemical is transferred from a drum into another container in the course example. What label is described?","The label described for a transferred chemical container is a _____ label.","workplace"],
  ["label-product","Product identifier","The product identifier names the product and should match its container/SDS information. It connects the container to the correct hazard information; the supplier identifier instead identifies the responsible company.",[21,23],"Which label element connects a container's product name to the correct SDS?","The product _____ names the chemical on the label.","identifier"],
  ["label-handling","Safe handling information","A workplace label includes safe handling information, a product identifier and an SDS reference. Handling information tells the worker how to use the product safely rather than merely naming it.",[23],"Which workplace-label element explains precautions for using the product?","A workplace label must include safe _____ information.","handling"],
  ["label-sds","Reference to the SDS","The SDS reference directs the worker to fuller product-specific information. The workplace label has less detail than the supplier label and is not a replacement for access to the SDS.",[23,27],"Which required workplace-label element points to more detailed product information?","A workplace label includes a reference to the _____.","SDS"],
  ["signal-word","Danger or Warning signal word","Signal words emphasize hazards and indicate severity on the supplied label example. They differ from hazard statements describing the hazards and precautionary statements describing protective measures.",[21],"Which label element uses Danger or Warning to emphasize hazard severity?","Danger and Warning are examples of a label's signal _____.","word"],
  ["hazard-statement","Hazard statement","Hazard statements are standardized descriptions of the product's hazards. Precautionary statements instead describe measures to minimize or prevent harm, so identifying a hazard and controlling it are separate messages.",[21],"Which label element describes the product's hazards in standardized wording?","A standardized description of a product's hazard is a hazard _____.","statement"],
  ["precaution-statement","Precautionary statement","Precautionary statements describe protective measures, including equipment and emergency measures. They explain responses or precautions rather than simply identifying the hazard's nature.",[21],"A label describes protective equipment and measures to prevent adverse effects. Which element is this?","Statements describing measures to minimize harm are _____ statements.","precautionary"],
  ["supplier-identifier","Supplier identifier","The supplier identifier names the responsible company that made, packaged, sold or imported the product. It identifies the supplier rather than the chemical itself.",[21],"Which label element identifies the company responsible for the label and SDS?","The _____ identifier names the responsible company on the label.","supplier"],
]);

topic("chemical-effects","Chemical effects, SDS use & waste","whmis",[
  ["acute","Acute toxic effects","The deck describes acute effects following a single overexposure, including serious immediate harm. Chronic effects instead can emerge days, months or years after one or more exposures.",[24,26],"Which term fits serious effects following a single overexposure?","Toxic effects associated with a single overexposure are described as _____.","acute"],
  ["chronic","Chronic toxic effects","Chronic effects can develop after a delay and include lung damage, cancer and reproductive effects in the lesson. A lack of immediate symptoms is therefore not proof that exposure caused no harm.",[26],"Which term describes harmful effects that may emerge months or years after exposure?","Delayed toxic effects that can appear months or years later are _____.","chronic"],
  ["ld","Lethal dose","LD stands for lethal dose. The course uses LD50 to discuss acute toxicity; it must not be confused with LC, which concerns concentration. Route and exposure conditions matter when comparing toxicity values.",[25,34,36],"In the toxicity abbreviations, what does LD identify?","LD expands to lethal _____.","dose"],
  ["lc","Lethal concentration","LC stands for lethal concentration. The inhalation example concerns a chemical's concentration in air over a specified time, whereas LD concerns an administered dose.",[25,35],"What does LC identify in the course's inhalation-toxicity example?","LC expands to lethal _____.","concentration"],
  ["ld-comparison","Smaller LD50 indicates greater acute toxicity in a comparable test","The lesson associates a smaller LD50 with greater acute toxicity. Compare like test conditions rather than treating the number as a universal safe human exposure or doing an exposure calculation.",[36],"For comparable test conditions, what does a smaller LD50 generally indicate?","For comparable tests, a smaller LD50 generally indicates _____ acute toxicity.","greater",["higher","more"]],
  ["sds-access","Product-specific SDS available to workers","An SDS contains detailed product-specific hazard information and must be available for workers to review. Workers need the sheet for the actual product, rather than assuming another product's information is interchangeable.",[27],"What reference should workers be able to review for detailed information on the actual hazardous product?","Detailed product-specific hazard information is provided in the _____.","SDS"],
  ["reactivity","Reactivity information","Reactivity information identifies instability, incompatible substances, conditions to avoid and hazardous decomposition. It helps recognize dangerous combinations rather than merely describing a product's colour or odour.",[32],"A worker needs to identify incompatible substances and conditions to avoid. Which information fits?","Information on instability and incompatible substances concerns _____.","reactivity"],
  ["hazard-waste","Contaminated absorbent managed as hazardous waste","The lesson says absorbent contacting hazardous waste is managed as hazardous waste. It must not be mixed with non-hazardous absorbents or put into drains; cleaning up transfers contamination rather than making it disappear.",[37],"What happens to absorbent after it contacts hazardous waste?","Absorbent contaminated by hazardous waste is managed as _____ waste.","hazardous"],
  ["rags","Designated fireproof containers for flammable-liquid rags","The deck directs flammable-liquid rags to designated fireproof containers. Leaving contaminated rags in ordinary waste undermines the fire-control measure identified in the lesson.",[37],"Where does the course direct rags containing flammable liquids?","Rags containing flammable liquids belong in designated _____ containers.","fireproof"],
]);

topic("confined-entry","Confined-space assessment & entry controls","confined",[
  ["confined-definition","Limited entry and not designed for occupancy","The course describes a space large enough to enter, with limited entry and not designed for occupancy, such as an aircraft fuel tank. Entry difficulty is only one feature; hazards must still be assessed.",[4],"Which description fits the course's aircraft fuel-tank confined-space example?","The fuel-tank example is not designed for regular _____.","occupancy"],
  ["assessment","Assessment of existing and developing hazards","The program identifies hazards present before work and those that may develop because of the work. An initial assessment alone is insufficient if the task changes the atmosphere or other conditions.",[6],"Which scope should the hazard assessment cover before confined-space work?","Existing hazards and those that may develop during work require an _____.","assessment"],
  ["permit","Entry permit","The program establishes a permit for each entry and records atmospheric test results on it. A permit documents the entry controls; it is not a substitute for actually testing and controlling hazards.",[6,19],"Which document records atmospheric test results and controls for a confined-space entry?","Each confined-space entry requires an entry _____.","permit"],
  ["outside-test","Atmospheric testing from outside before entry","The air should be tested from outside the space before entry and the results recorded. Entering first to take a sample would expose the tester before the atmosphere has been assessed.",[19],"Where should pre-entry atmospheric testing be carried out from?","Pre-entry air testing should be performed from _____ the space.","outside"],
  ["unsafe-entry","Do not enter until the space is made safe","The lesson says workers must not enter when precautions have not made the space safe. A deadline or an entry permit alone does not eliminate the unresolved hazard.",[25],"Precautions have not made a confined space safe. What is the appropriate entry decision?","Workers must not _____ a confined space that has not been made safe.","enter"],
  ["isolation","De-energize and lock out hazardous sources","Potentially hazardous energy must be de-energized and locked out before entry. The control addresses unexpected movement or release, not just the atmospheric hazard inside a tank.",[23,32,47],"Which control addresses unexpected equipment activation before confined-space entry?","Hazardous energy sources must be de-energized and locked _____ before entry.","out"],
  ["entry-opening","Opening accommodates a worker wearing protective equipment","The entry/exit opening must allow passage while wearing the required protective equipment. An opening that fits an unprotected worker may still be inadequate for the planned protected entry.",[23],"What must the entry opening accommodate besides the worker's body?","The entry opening must accommodate the worker's protective _____.","equipment"],
  ["supervisor","Entry supervisor","The entry supervisor authorizes the work and ensures it follows procedure. This differs from the standby attendant's outside monitoring role and the entrant's work inside the tank.",[33],"Who authorizes fuel-tank entry work and ensures it follows procedure?","The entry _____ authorizes work and ensures the procedure is followed.","supervisor"],
  ["attendant","Standby attendant outside the tank","The attendant stays outside and monitors conditions in and around the work area. That outside role is essential for communication and ordering evacuation if conditions change.",[33,35],"Who stays outside the tank to monitor entry conditions?","The standby _____ monitors the tank entry from outside.","attendant"],
  ["evacuation","Evacuate when conditions deteriorate","The attendant can order evacuation when conditions put entrants at risk; entrants must recognize hazards and leave when conditions deteriorate. An earlier acceptable test does not authorize staying through a later unsafe change.",[35],"Conditions become unsafe while personnel are inside the tank. What response does the lesson require?","Entrants must _____ if working conditions deteriorate.","evacuate",["leave"]],
  ["communication","Continuous communication with the outside attendant","The course calls for continuous voice communication during fuel-tank entry and describes visual/verbal/electronic communication more generally. Communication links the outside monitor with the worker inside.",[36,53],"Which control keeps the attendant and entrant in contact throughout entry?","Continuous _____ must be maintained between entrants and the attendant.","communication"],
  ["tools-air","Compressed air rather than nitrogen for pneumatic tools","The deck says pneumatic tools should use compressed air, not nitrogen or another inert gas. An inert gas can displace oxygen, so absence of combustion is not the same as breathable air.",[37],"What should power pneumatic tools in the confined-space example?","The deck specifies compressed air rather than _____ for pneumatic tools.","nitrogen"],
  ["electrical-rating","Intrinsically safe or suitably rated electrical equipment","Electrical equipment must be intrinsically safe or rated for the potentially flammable atmosphere. An ordinary powered tool is not acceptable merely because it fits through the entry opening.",[37],"Which electrical equipment is described for a potentially flammable tank atmosphere?","One accepted equipment description is intrinsically _____.","safe"],
  ["ventilation","Ventilation maintained during work","Purging removes contaminants, while ventilation helps keep them from accumulating during the task. A clean initial atmosphere can change as work proceeds, so ongoing control matters.",[31,51],"Which control helps prevent airborne contaminants building up while work continues?","Airborne contaminants are controlled during work with _____.","ventilation"],
  ["monitoring","Continuous atmospheric monitoring","The lesson asks whether provisions exist to monitor the atmosphere continually during work. A pre-entry reading is only a measurement at that time; changing conditions require continued monitoring.",[47],"Which check is needed after an acceptable pre-entry atmospheric test?","The atmosphere needs continuous _____ during confined-space work.","monitoring"],
  ["flammable-range","Concentration between lower and upper flammable limits","The lesson places the flammable range between LFL and UFL. A meter reading must be interpreted correctly, and a flammability result alone does not establish acceptable oxygen or toxic exposure.",[7,42,45],"Which relationship describes the flammable range in the lesson?","The flammable range lies _____ the lower and upper flammable limits.","between"],
  ["meter","Percentage of LEL rather than total gas concentration","The explosimeter example reports a percentage of the lower explosive limit. That is not the gas's percentage of the whole atmosphere, and the deck warns that low flammability readings can still coexist with toxicity.",[42,45],"What does a percentage reading on the lesson's explosimeter represent?","The meter reading is a percentage of the lower explosive _____.","limit"],
  ["blanking","Blanking hazardous supply lines when required","The lesson warns that closing a valve may not adequately isolate a hazardous line, because it could be opened inadvertently. Blanking may be required to prevent material entering the space.",[46,48],"What additional line-isolation measure may be required when a closed valve is insufficient?","Where closing a valve is inadequate, the lesson identifies _____ of the line.","blanking"],
]);

topic("rescue","Confined-space rescue planning","confined",[
  ["rescue-plan","Preplanned, trained and equipped emergency response","The program includes an emergency plan with training, equipment and a response system. Waiting until someone collapses to decide on rescue exposes both the entrant and would-be rescuers to avoidable risk.",[13,39,52],"Which arrangement should be established before a confined-space emergency occurs?","The emergency response arrangement must be _____ before entry.","planned",["preplanned"]],
  ["outside-rescue","Rescue from outside where possible","The deck prefers rescue from outside the space when possible. This avoids exposing another person to the same atmosphere; entry rescue still requires trained, equipped personnel and the rescue plan.",[39,40],"What rescue approach avoids exposing another person to the tank atmosphere where feasible?","Where possible, rescue should be performed from _____ the space.","outside"],
  ["trained-rescuer","Only trained and equipped entry rescuers","A coworker must not improvise an entry rescue. The lesson requires rescue training, suitable protective equipment and another qualified rescuer outside before rescue entry.",[40,52],"A coworker collapses in a fuel tank. Who may perform an entry rescue?","Entry rescuers must be properly equipped and _____.","trained"],
  ["rescue-air","Independent breathing-air supply for rescue","The deck says rescuers should not use the same air as those being rescued and identifies SCBA or supplied air with an escape bottle. A second person breathing the hazardous tank atmosphere can become another casualty.",[40],"What distinguishes the breathing protection described for rescue entry?","Rescuers must not depend on the tank's contaminated breathing _____.","air"],
]);

topic("flight-line","Flight-line hazards & foreign-object damage","ramp",[
  ["hearing-external","Earmuff-type external hearing protection","External earmuff protection reduces sound reaching the eardrum. Internal protection fits into the auditory canal; both are hearing controls rather than guarantees against every flight-line hazard.",[7,8],"Which hearing protection type fits around the ears rather than into the auditory canal?","External hearing protection in the lesson uses _____-type protectors.","earmuff",["earmuffs"]],
  ["hearing-internal","Internal protection fitted into the auditory canal","The internal type fits into the auditory canal to reduce sound reaching the eardrum. Short exposure to noisy tools can still cause harm, so duration alone does not justify skipping protection.",[7,8],"Which type of hearing protection fits into the auditory canal?","The protection fitted into the auditory canal is the _____ type.","internal"],
  ["pilot-view","Stay in the pilot's field of vision","The deck warns not to assume the pilot sees a technician near a taxiing aircraft. Staying visible supports coordination, while engine intakes, exhaust and propellers remain separate hazards.",[9,12],"A technician is near a taxiing aircraft. Which visibility practice does the deck emphasize?","Stay in the pilot's field of _____.","vision",["view"]],
  ["secure-gse","Secure support equipment and allow aircraft clearance","Equipment must be stowed or secured so it cannot roll into the aircraft. Clearance and restraint matter even when the support equipment is not being actively driven.",[10],"How should support equipment be left near operating aircraft?","Support equipment should be stowed or _____ against movement.","secured"],
  ["ignition","No smoking or open flames near operating aircraft","The flight-line lesson identifies flammable liquids and gases and excludes smoking/open flames near aircraft in operation. Fire prevention controls ignition sources instead of relying only on extinguishing a fire later.",[11],"Which practice addresses ignition sources near aircraft in operation?","Smoking and open _____ are excluded near aircraft in operation.","flames",["flame"]],
  ["tail-rotor","Avoid the tail rotor and the rear approach","A rotating tail rotor can be difficult to see. The lesson says never approach a single-rotor helicopter from the rear or pass around/under the tail, and describes going around the nose instead.",[18],"Which helicopter hazard explains avoiding the rear and tail area?","The rotor specifically associated with the rear-approach hazard is the _____ rotor.","tail"],
  ["carry-low","Keep carried items clear of rotor blades","The deck warns against carrying objects high enough to contact blades and calls for maximum clearance. A long object held upright can enter a rotor's space even if the person remains below it.",[18,19],"What precaution applies when carrying items near a helicopter's rotor?","Carried items must stay clear of rotor _____.","blades",["blade"]],
  ["rotor-securing","Use the maintenance manual to secure a rotor","The lesson says to check the maintenance manual for the proper securing method because an incorrect method can damage a bearing. A convenient improvised restraint is not automatically suitable.",[19],"Where should a technician find the proper method for securing a helicopter rotor?","The proper rotor-securing method comes from the maintenance _____.","manual"],
  ["fod-intake","Intake suction can draw loose objects into an engine","The low-pressure area ahead of a turbine intake can draw in loose objects. Keeping tools away from intakes and controlling debris prevents damage rather than waiting to inspect after ingestion.",[28,29],"Why are tools and loose hardware especially dangerous near a turbine intake?","The intake's low-pressure area can draw loose objects _____ the engine.","into"],
  ["fod-exhaust","Exhaust can propel loose objects","The deck describes exhaust throwing loose objects with enough force to damage what they strike. FOD control protects people and equipment outside the engine as well as the engine itself.",[28],"Why must loose debris also be controlled behind a turbine engine?","Engine _____ can propel loose debris at damaging force.","exhaust"],
  ["fod-control","Clean work areas, tool control and convenient waste receptacles","The FOD program combines cleaning operating areas, accounting for tools and providing places for used hardware/towels. These controls keep loose items from becoming intake or exhaust hazards.",[26,27],"Which combination most directly supports the FOD prevention program described?","Accounting for tools is called tool _____.","control"],
  ["shadow-board","Visible tool inventory such as a shadow board","The deck recommends foam cutouts, shadow boards, descriptions, pictures and inventories to reveal missing tools at a glance. This makes a missing item visible before it is forgotten in an aircraft.",[39],"Which method helps reveal a missing tool at a glance?","A tool-outline display is a shadow _____.","board"],
]);

topic("professionalism","Paperwork, parts control & professional conduct","ramp",[
  ["paper-sign","Sign only completed work promptly","The deck says to sign or initial only when the task is complete and as soon as completed. Signing planned work misrepresents completion; waiting until the entire job ends loses the task-by-task record.",[36],"When should the technician sign or initial a maintenance task?","A task must be _____ before it is signed off.","completed",["complete","finished"]],
  ["paper-correction","Single-line correction with initials","The lesson preserves the original entry with a single strike-through and initials rather than white-out. Legibility and traceable correction preserve the record instead of hiding what was changed.",[36],"How does the course describe correcting a paperwork mistake?","The lesson calls for a single _____ through the mistake, with initials.","line"],
  ["parts-id","Keep parts with identification and correct reference material","Parts should remain clean/protected and associated with packages carrying descriptions and part numbers. Correct references and diagrams support installing the correct part in the correct location.",[40],"Which practice helps prevent an unidentified or incorrectly located replacement part?","Keep parts associated with their descriptions and part _____.","numbers",["number"]],
  ["ask","Ask for clarification or help","The lesson says to clarify misunderstood instructions and ask for help with tasks better done by two people. Guessing to look independent can compromise the task and the aircraft.",[35],"An instruction is unclear. What professional response does the deck recommend?","Ask for _____ when an instruction is not understood.","clarification"],
  ["privacy","Protect customer property and privacy","The deck calls for protecting the aircraft and possessions from damage/dirt and respecting personal items and sensitive documents. Access for maintenance is not permission to browse unrelated belongings.",[41],"What obligation applies to a customer's unrelated personal items and documents?","Respect the customer's _____ when encountering personal documents.","privacy"],
  ["ethics-repair","Do not compromise repair standards for the schedule","The ice-shield case describes pressure to use an unauthorized repair after discovering missing stock. The technician's refusal illustrates that schedule pressure does not establish a valid repair or facility authorization.",[45,46,47],"An approved replacement is unavailable and a supervisor proposes an unauthorized cosmetic fix. What principle fits the case?","In the case study, schedule pressure did not justify compromising repair _____.","standards"],
]);

topic("towing","Towing team, equipment & movement controls","towing",[
  ["tug","Tow tractor or tug","Large aircraft are usually moved using a tow tractor, called a tug. Small aircraft may be hand-moved only at suitable areas; that does not make every aircraft surface a pushing point.",[5,26],"What equipment usually moves large aircraft in the towing lesson?","A tow tractor is also called a _____.","tug",["mule"]],
  ["towbar","Correct tow bar for the aircraft","The deck distinguishes general-purpose and aircraft-specific bars and requires the proper bar. Tensile strength alone does not make a bar suitable for twisting loads or every aircraft attachment.",[7,9,26],"Which equipment-selection requirement applies before towing?","Use the correct tow _____ for the aircraft.","bar"],
  ["bar-inspection","Inspect tow-bar engaging devices","Before movement, the lesson calls for checking engaging devices for damage or malfunction. Discovering a defective connection after movement risks loss of control or separation.",[8],"What should be checked on the attached tow bar before moving the aircraft?","Inspect tow-bar engaging _____ for damage or malfunction.","devices",["device"]],
  ["brake-person","Qualified person in the flight deck for braking","The deck places a qualified person in the flight deck to operate brakes if the bar fails or unhooks. Aircraft-specific procedures govern braking coordination; the deck's inconsistent routine-braking wording is not a universal instruction.",[6,10,36],"Which staffing measure provides aircraft braking capability if the tow bar fails?","A _____ person must occupy the flight deck for the described braking role.","qualified"],
  ["wing-walker","Wing walkers at the wingtips","A walker at each wingtip checks clearance from obstructions along the route. A tug driver cannot be assumed to see every wingtip clearance while controlling the vehicle.",[11,19],"Who checks obstruction clearance at each wingtip during the described tow?","The team member watching a wingtip is a wing _____.","walker"],
  ["tail-walker","Tail walker for sharp turns or backing","The lesson assigns a tail walker when making sharp turns or backing into position. This supplements wingtip coverage where the tail's path needs additional observation.",[11,19],"Which additional observer is assigned for sharp turns or backing?","For sharp turns or backing, assign a _____ walker.","tail"],
  ["walking-speed","No faster than the walking team","The deck limits towing speed to that of walking team members. The people monitoring clearance need to keep pace and remain effective; an empty-looking ramp is not a reason to outrun them.",[14,33],"What sets the towing-speed limit in the team's walking-speed example?","Towing must not exceed the speed of _____ team members.","walking"],
  ["no-between","Keep everyone out from between the tug and nosewheel","The deck prohibits walking or riding between the nosewheel and towing vehicle. The moving aircraft/tug connection creates a dangerous area even during a slow tow.",[13,33],"Which area must remain clear of walking or riding personnel during towing?","Nobody may walk or ride _____ the tug and aircraft nosewheel.","between"],
  ["no-board","Do not board or leave a moving aircraft or tug","The course prohibits boarding or leaving the moving aircraft or towing vehicle. Stopping first avoids exposing a person to movement while stepping between surfaces.",[13,33],"A person needs to get on or off during a tow. Which restriction applies?","Do not board or leave the aircraft or tug while it is _____.","moving"],
  ["chocks","Chocks immediately available for emergencies","The deck calls for chocks to be immediately available throughout towing. Their emergency availability is separate from the qualified flight-deck braking role and does not excuse unsafe towing practices.",[15,34],"What equipment must be immediately available throughout the towing operation?","Emergency _____ must be immediately available throughout a tow.","chocks",["chock"]],
  ["doors-locks","Close doors, retract ladders and install gear-down locks","The lesson identifies doors, ladders and gear-down locks as pre-tow preparation items. Proper configuration reduces damage/injury risks as the aircraft begins moving.",[16],"Which combination is identified as pre-tow configuration preparation?","The landing gear should have the specified gear-down _____ installed before the described tow.","locks",["lock"]],
  ["inflation","Check tire and landing-gear-strut inflation","The lesson calls for inflation checks before towing, with a stated overhaul/storage exception for struts. This is a condition check rather than a rule to inflate every strut without referring to aircraft requirements.",[16],"Which landing-gear condition check does the lesson identify before towing?","Check tires and landing-gear struts for proper _____.","inflation"],
  ["hand-pressure","Push only at structurally suitable approved areas","For manual movement of small aircraft, pressure belongs at areas strong enough to withstand it without damage. An accessible skin panel is not necessarily a suitable pushing point.",[5,29],"Where may hand pressure be applied when manually moving a small aircraft?","Hand-pushing areas must have sufficient structural _____.","strength"],
  ["stop-command","Obey an emergency stop from any team member","The towing vehicle operator must obey an emergency-stop instruction from any team member. A wing or tail observer may see a hazard that the driver cannot see.",[29],"Who can give an emergency-stop instruction that the tug operator must obey?","An emergency stop from _____ team member must be obeyed.","any"],
  ["constant-contact","Constant tug-to-flight-deck communication","The towing vehicle operator must maintain communication with the aircraft's cockpit operator. Coordination is needed throughout movement rather than only before departure.",[27],"Which communication link is required throughout the described large-aircraft tow?","The tug and flight-deck operators must maintain constant _____.","communication"],
  ["prop-live","Treat propellers as though ignition is on","The towing lesson says to treat all propellers as though ignition is on. This precaution prevents relying on assumptions about the switch position when working around a propeller.",[27],"What assumption should guide propeller precautions in the towing lesson?","Treat propellers as though the ignition is _____.","on"],
]);

topic("loto","Isolation, stored energy & restoration","loto",[
  ["physical-lock","Physical barrier preventing activation or energy flow","LOTO prevents unexpected energization, activation or release of hazardous energy. A physical barrier secures isolation; simply warning people does not itself remove the hazard.",[5,8,10],"What distinguishes physical lockout from a warning notice?","Lockout places a physical _____ against activation or energy flow.","barrier"],
  ["placard","Placard warns but does not remove the hazard","A placard alerts people to possible danger but does not remove the hazard. It must not be confused with securing an isolation/control device against operation.",[8],"What is the limitation of a placard in the lesson?","A placard _____ people to danger without removing the hazard.","alerts",["warns"]],
  ["verify-isolation","Verify isolation and release stored energy before work","The lesson requires verifying isolated hazards and releasing stored energy before starting. Switching off a supply is not sufficient if trapped pressure, springs or other energy remain.",[9,10,21],"After identifying and isolating sources, what must happen before work begins?","Stored energy must be _____ as required before work begins.","released",["discharged"]],
  ["gpu-tags","Tag GPU controls and cable ends","The GPU example tags the controls and cable ends. Identifying only one point may leave another part of the external-power connection unrecognized; the correct equipment procedure governs isolation.",[13],"Which points are identified for tagging on the portable ground-power example?","The GPU example tags its controls and cable _____.","ends",["end"]],
  ["spring-energy","Springs retain mechanical energy","Landing-gear springs can store substantial energy, including springs hidden inside cylinders or propeller hubs. Removing electrical power does not by itself eliminate this mechanical hazard.",[20,21],"Why can a spring remain hazardous after electrical power is disconnected?","Springs can retain _____ energy after electrical power is removed.","mechanical"],
  ["fuel-isolation","Lock closed the relevant fuel-flow isolation","For an open fuel tank under maintenance, the lesson identifies locking fuel valves closed and grounding against static sparks. A warning alone does not physically stop fuel flow into the work area.",[19],"Which fuel-flow control is described for an open tank under maintenance?","The relevant fuel valves are locked _____ in the example.","closed"],
  ["ground-static","Grounding to prevent static sparks","The fuel-maintenance example calls for grounding the aircraft to prevent static sparks. This controls an ignition hazard and does not replace fuel-flow isolation or tank-entry controls.",[19],"What does grounding address in the fuel-tank maintenance example?","Grounding helps prevent _____ electricity sparks.","static"],
  ["gear-pin","Specified gear-down pin prevents retraction or collapse","The illustrated example's top pin prevents landing-gear retraction and collapse if gear-up is selected. The slide's top/bottom labels refer to that illustration and are not universal installation instructions.",[17,18],"In the deck's illustrated top-pin example, what hazard does that pin prevent?","The specified gear-down pin prevents accidental gear _____.","retraction"],
  ["steering-pin","Specified steering bypass pin keeps cylinders unpressurized","The illustrated example's bottom pin keeps steering cylinders in bypass and unpressurized. That function differs from supporting the aircraft against gear retraction; actual pin identification is aircraft-specific.",[17,18],"What does the illustrated steering-bypass pin do in this course example?","The example's steering pin keeps the cylinders in _____.","bypass"],
  ["job-cards","Confirm completed job cards and LOTO sign-offs","Before restoring power, the deck checks completed job cards and the LOTO control signature book. Documentation helps establish that affected groups have completed the required work and sign-offs.",[23],"Which documentation should be checked before power restoration?","Check completed job cards and LOTO control _____.","sign-offs",["signoffs"]],
  ["restore-communicate","Communicate before and during power restoration","The lesson calls for contact with coworkers, supervisors and group leaders, announcements, and communication between cockpit and ground personnel. Restoration is a coordinated activity rather than one person's unannounced switch action.",[23],"Which communication practice accompanies restoring power?","Power restoration requires continuous _____ with affected crew members.","communication"],
  ["restore-walkaround","Reinspect and walk around before restoring power","The restoration checklist includes checking systems and areas, walking around and confirming people are clear and aware. A completed signature book alone does not replace physically checking the area.",[23],"Besides paperwork and communication, which physical check precedes restoring power?","Before restoration, the lesson calls for a walk-_____ inspection.","around"],
]);

// Expand each named energy source separately instead of one catch-all question.
topic("energy","Each hazardous-energy source","loto",[
  ["energy-electrical","Electrical energy","Electrical power is one hazardous-energy source. The deck shows circuit breakers and external power examples; other forms of energy can remain after electrical isolation.",[10,11,12,13],"Which energy category is associated with circuit breakers and external power?","Circuit breakers and external power are associated with _____ energy.","electrical"],
  ["energy-mechanical","Mechanical energy","Mechanical energy includes the spring hazards identified in the course. Hidden springs can remain loaded even after power is switched off, so stored energy must be addressed.",[10,11,21],"Which energy category includes the loaded springs identified in the lesson?","Loaded springs are a source of _____ energy.","mechanical"],
  ["energy-hydraulic","Hydraulic energy","The deck identifies hydraulic energy separately from electrical and pneumatic energy. Isolating electrical controls does not by itself establish that a pressure-containing system has no stored energy.",[10,11,14],"Which energy category concerns the hydraulic-pressure example?","The pressure-system category named for hydraulics is _____ energy.","hydraulic"],
  ["energy-pneumatic","Pneumatic energy","Pneumatic energy is a distinct source in the lesson, with a valve-isolation example. Stored pressure and unintended activation need the applicable isolation controls.",[10,11,16],"Which energy category is identified for the pneumatic-valve example?","The valve example identified as pneumatic concerns _____ energy.","pneumatic"],
  ["energy-chemical","Chemical energy","Chemical energy is one of the hazardous-energy categories named in the deck. LOTO planning must identify relevant sources rather than assuming that electrical disconnection addresses every hazard.",[10,11],"Which category in the source list concerns energy associated with chemicals?","The source list names _____ energy alongside electrical and thermal energy.","chemical"],
  ["energy-thermal","Thermal energy","Thermal energy is separately named as a hazardous-energy source. A source inventory must include relevant heat-related hazards rather than focusing solely on moving equipment.",[10,11],"Which listed energy category concerns heat?","Heat-related hazardous energy is described as _____.","thermal"],
  ["energy-gravity","Gravitational energy","The deck's weight/gravity examples include preventing landing-gear collapse. Disconnecting a power supply does not remove an aircraft's weight or the potential for downward movement.",[10,11,17],"Which energy source explains why gear-collapse protection is needed even with power off?","Weight and possible downward movement concern _____ energy.","gravitational",["gravity"]],
  ["energy-flow","Flow","Flow is separately listed and illustrated with fuel-valve isolation. Preventing liquid from reaching an open tank is a different control from merely displaying a warning placard.",[11,19],"Which additional source-list item is illustrated by closing and locking fuel valves?","Fuel-valve isolation prevents unwanted fuel _____.","flow"],
]);

topic("exposure","Each chemical route of entry","whmis",[
  ["skin-contact","Skin contact","Skin contact is a route of exposure listed in the toxicological information. Contact concerns material touching skin; absorption concerns material entering through it, so the two descriptions are not identical.",[33],"Which listed exposure description means material touching the skin?","Material touching skin is skin _____.","contact"],
  ["skin-absorption","Skin absorption","Skin absorption is listed separately from skin contact. Material entering through the skin is an exposure route even when it was not swallowed or breathed in.",[33],"Which listed route involves a chemical entering through skin?","A chemical entering through the skin involves skin _____.","absorption"],
  ["eye-contact","Eye contact","Eye contact is a listed exposure route and must be considered alongside inhalation, ingestion and skin routes. Assessing only what a worker breathes can miss direct eye exposure.",[33],"Which listed route specifically concerns chemical contact with the eyes?","Chemical contact with the eyes is _____ contact.","eye"],
  ["inhalation","Inhalation","Inhalation is exposure by breathing material in. The course's LC example concerns concentration in air; ingestion instead concerns material entering by swallowing.",[33,35],"Which route involves breathing a chemical in?","Breathing a chemical in is _____.","inhalation"],
  ["ingestion","Ingestion","Ingestion involves swallowing a substance and is distinct from breathing it in. The route matters when interpreting toxicological information; one route's data should not be casually substituted for another.",[33,34],"Which exposure route involves swallowing a chemical?","Swallowing a chemical is _____.","ingestion"],
]);

