const acronyms=[
  ["WSIB","Workplace Safety and Insurance Board","Insurance","whmis",[4,5]],
  ["OHSA","Occupational Health and Safety Act","Occupational","whmis",[4,6]],
  ["WHMIS","Workplace Hazardous Materials Information System","Materials","whmis",[12,13]],
  ["SDS","Safety Data Sheet","Data","whmis",[13,27]],
  ["LOTO","Lock Out Tag Out","Tag","loto",[1,5]],
  ["GPU","Ground Power Unit","Power","loto",[13]],
  ["RAT","Ram Air Turbine","Turbine","loto",[20]],
  ["FOD","Foreign Object Damage","Object","ramp",[25]],
  ["APU","Auxiliary Power Unit","Auxiliary","ramp",[5]],
  ["LFL","Lower Flammable Limit","Lower","confined",[7]],
  ["UFL","Upper Flammable Limit","Upper","confined",[7]],
  ["LEL","Lower Explosive Limit","Explosive","confined",[29,42]],
  ["TLV","Threshold Limit Value","Threshold","confined",[45]],
  ["SCBA","Self Contained Breathing Apparatus","Breathing","confined",[40]],
  ["PPE","Personal Protective Equipment","Protective","confined",[40]],
];
const acronymItems=[];
const acronymDistractors={
  WSIB:["Workers Safety and Inspection Board","Workplace Standards and Insurance Bureau","Workplace Safety and Inspection Board"],
  OHSA:["Occupational Health and Safety Administration","Ontario Hazardous Substances Act","Occupational Hazard and Security Act"],
  WHMIS:["Workplace Hazardous Materials Inspection System","Workplace Health Materials Information Standard","Worker Hazard Management Information System"],
  SDS:["Safety Description Standard","Supplier Data Statement","Substance Disposal Sheet"],
  LOTO:["Lock Open Tag Open","Local Operation Test Order","Lock Out Test Operation"],
  GPU:["Ground Pressure Unit","General Power Utility","Ground Protection Unit"],
  RAT:["Ram Air Temperature","Rotor Actuation Tool","Rotating Air Turbine"],
  FOD:["Foreign Object Detection","Fuel Overflow Damage","Flight Operation Defect"],
  APU:["Aircraft Pressure Unit","Auxiliary Protection Unit","Air Power Utility"],
  LFL:["Lower Flash Level","Low Fuel Limit","Lower Flammable Load"],
  UFL:["Upper Flash Level","Upper Fuel Load","Upper Flammable Level"],
  LEL:["Lower Exposure Level","Low Energy Limit","Lower Explosive Load"],
  TLV:["Total Limit Volume","Toxic Load Value","Threshold Level Volume"],
  SCBA:["Self Controlled Breathing Air","Supplied Chemical Breathing Apparatus","Self Contained Body Air"],
  PPE:["Personal Pressure Equipment","Personnel Protection Evaluation","Portable Protective Enclosure"],
};
const acronymContext={
  WSIB:"The course's insurance example links employer premiums with injured workers' earnings benefits and health-care coverage.",
  OHSA:"The deck identifies Ontario's workplace health and safety legislation, distinct from its federal Canada Labour Code discussion.",
  WHMIS:"The system combines labels, SDSs and worker education so hazardous-product information can be used at work.",
  SDS:"The sheet provides detailed product-specific information; access to it complements the information on the container label.",
  LOTO:"Isolation and control of stored energy prevent unexpected activation or release during maintenance; a warning placard alone does not remove the hazard.",
  GPU:"The external-power example requires tagging the controls and cable ends, so both parts of the connection are identified.",
  RAT:"The deck lists the ram air turbine in its mechanical-energy examples; the applicable aircraft procedure governs its isolation.",
  FOD:"Loose hardware, rags and tools can cause damage through intake ingestion or exhaust-propelled impact, so tool control and housekeeping matter.",
  APU:"The deck includes auxiliary-power units among flight-line noise sources, making them relevant to awareness and hearing protection.",
  LFL:"This is the lower boundary of the flammable range; the deck places that range between the lower and upper limits.",
  UFL:"This is the upper boundary of the flammable range, distinct from the lower limit and from a toxic-exposure criterion.",
  LEL:"The explosimeter example gives a percentage of this limit, not a direct percentage of gas in the total atmosphere.",
  TLV:"The deck uses this exposure concept to explain why a low flammability reading can still coexist with a toxic atmosphere.",
  SCBA:"The rescue lesson identifies breathing protection independent of the hazardous atmosphere, rather than sharing the air that harmed the entrant.",
  PPE:"The rescue lesson requires appropriate protective equipment as well as training; being willing to help is not enough for safe entry rescue.",
};
for(const [code,name,word,deck,slides] of acronyms) {
  const words=name.split(" ");
  const letters=words.filter(w=>w!=="and").map(w=>`${w[0]} = ${w.toLowerCase()}`).join("; ");
  const explanation=`${code} means ${name}. ${letters}. ${acronymContext[code]} (${safetyModule2Sources[deck].title}, slides ${slides.join(", ")}.)`;
  safetyModule2Choice.push({id:`safety2-acronym-${code}`,topic:"acronyms",learningTarget:`acronym-${code}`,prompt:`What does ${code} stand for in these course notes?`,options:[name,...acronymDistractors[code]],correctIndex:0,explanation,source:{deck,slides}});
  safetyModule2Recall.push({id:`safety2-word-acronym-${code}`,topic:"acronyms",learningTarget:`acronym-${code}`,prompt:`Complete ${code}: ${words.map(w=>w===word?"_____":w).join(" ")}.`,answer:word.toLowerCase(),acceptedAnswers:[word.toLowerCase()],explanation,source:{deck,slides}});
  acronymItems.push([code,explanation]);
}
safetyModule2NoteSections.push({id:"safety2-acronyms",title:"Acronyms — each word and letter",items:acronymItems});

