// Stable, separate part banks; each part is a complete saved test, never sampled.
function parts(bank,kind) {
  const count=Math.ceil(bank.length/39),size=Math.floor(bank.length/count),extra=bank.length%count;
  let offset=0;
  return Array.from({length:count},(_,i)=>{
    const questions=bank.slice(offset,offset+size+Number(i<extra));offset+=questions.length;
    const suffix=`${kind==="choice"?"practice":"one-word"}-${i+1}`;
    const path=`${safetyModule2Path}/${suffix}`;
    return {slug:`safety-module2-${kind}-${i+1}`,course:"Safety",courseSlug:"safety",basePath:safetyModule2Path,path,storageId:path,kind,questions,number:i+1,difficulty:kind==="choice"?"medium":"hard",title:`${kind==="choice"?"Notes Practice":"One-Word Recall"} · Part ${i+1}`};
  });
}
export const safetyModule2Parts=[...parts(safetyModule2Choice,"choice"),...parts(safetyModule2Recall,"typed")];
